//! Phase 071 — MCTS-sourced episode generation for GRPO training.
//!
//! Phase 70's honest diagnosis: GRPO training episodes generated by raw
//! policy sampling (`trainable_rollout::sample_episode`) almost always
//! fail outright on this domain, so most groups have ~zero reward
//! variance and therefore ~zero gradient. The fix: generate training
//! episodes via MCTS (which finds some successes even when raw sampling
//! can't).
//!
//! The same (current) policy is used as MCTS's rollout_policy for the
//! simulation phase, but the actual *episode* returned is the
//! AlphaZero-style visit-count-greedy path from the search tree root —
//! visit counts encode MCTS's improvement over the raw policy at every
//! node, not just the lucky leaf.
//!
//! log_prob at each step is still the CURRENT policy's own log_prob of
//! the action MCTS ended up preferring, so PPO/GRPO's ratio machinery
//! r = pi_new/pi_old is unchanged — only which actions get taken, and
//! hence which rewards get observed, changes.

use std::rc::Rc;

use rand::rngs::StdRng;
use rand::Rng;
use reasoning_search::{Domain, Mcts, NtState, NumberTargetDomain};

use crate::policy::SoftmaxPolicy;
use crate::reward_model::reward_from_verification_result;
use crate::trainable_rollout::{Episode, TrainableRollout};

/// Returns `(episode, reward, passed)`. `episode.states[i]` is the state
/// `episode.actions[i]` was taken from (same parallel-list convention as
/// `trainable_rollout::sample_episode`, so this is a drop-in alternative
/// episode source).
///
/// Python signature:
/// `sample_episode_via_mcts(policy, domain, initial_state, target,
/// max_depth, depth_fn, rng, num_simulations=150, rollout_epsilon=0.1)`.
/// In this port MCTS owns the RNG stream (seeded from `rng`); the
/// trainable rollout receives that same stream through the
/// `RolloutPolicy::choose` interface, mirroring Python's shared `rng`.
pub fn sample_episode_via_mcts(
    policy: &SoftmaxPolicy,
    domain: &NumberTargetDomain,
    initial_state: &NtState,
    target: f64,
    max_depth: usize,
    depth_fn: Rc<dyn Fn(&NtState) -> usize>,
    rng: &mut StdRng,
    num_simulations: usize,
    rollout_epsilon: f64,
) -> (Episode, f64, bool) {
    let rollout = TrainableRollout::new(
        policy.clone(),
        domain.clone(),
        target,
        max_depth,
        depth_fn.clone(),
        rollout_epsilon,
    );
    let seed = rng.gen::<u64>();
    let mut mcts = Mcts::new(domain.clone(), max_depth, seed)
        .with_rollout_policy(Box::new(rollout));
    let result = mcts.search(initial_state.clone(), num_simulations);

    let mut ep = Episode::new();
    let mut node_idx = result.root;
    let mut state = initial_state.clone();
    let mut depth = 0usize;
    loop {
        let children = result.tree[node_idx].children.clone();
        if children.is_empty() || depth >= max_depth {
            break;
        }
        // Python `max(node.children, key=lambda c: c.visit_count)`: ties
        // break toward the FIRST child.
        let mut best = children[0];
        for &c in &children[1..] {
            if result.tree[c].visit_count > result.tree[best].visit_count {
                best = c;
            }
        }
        if result.tree[best].visit_count == 0 {
            break; // this subtree was never actually explored; stop here
        }
        let legal = domain.legal_actions(&state);
        let action = result.tree[best]
            .action_from_parent
            .clone()
            .expect("tree children always carry an action");
        if !legal.contains(&action) {
            break; // defensive: state/action bookkeeping mismatch, stop rather than guess
        }
        let lp = policy.log_prob(&state, &action, &legal, domain, target, max_depth, depth_fn.as_ref());
        ep.states.push(state.clone());
        ep.actions.push(action);
        ep.legals.push(legal);
        ep.log_probs.push(lp);
        state = result.tree[best].state.clone();
        node_idx = best;
        depth += 1;
        if domain.is_terminal(&state) {
            break;
        }
    }

    let passed =
        domain.is_terminal(&state) && domain.terminal_reward(&state) >= 0.999;
    let reward = reward_from_verification_result(passed);
    (ep, reward, passed)
}
